@PEutt.peutt
     : forall (E MN MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF),
       @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI ->
       TwoLevelMeasure.MixedMeasure MN MF ->
       @TwoLevelMeasure.SemanticOmega MF FI ->
       forall R1 R2 : Type,
       (R1 -> R2 -> Prop) -> PTreeDefinition.ptree E MN R1 -> PTreeDefinition.ptree E MN R2 -> Prop

@PEutt.peutt_bind
     : forall (E MN MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF)
         (FC : @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI),
       @TwoLevelMeasure.SemanticMeasureBindLaws MF FI ->
       forall (MX : TwoLevelMeasure.MixedMeasure MN MF) (FO : @TwoLevelMeasure.SemanticOmega MF FI),
       @TwoLevelMeasure.SemanticMeasureOrderLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaCofinalityLaws MF FI FO ->
       @TwoLevelMeasure.SemanticMeasureDiagonalLaws MF FI FO ->
       (forall (A R : Type) (t : PTreeDefinition.ptree E MN A)
          (k : A -> PTreeDefinition.ptree E MN R),
        @PTreeKernel.ptree_bind_cofinal E MN MF FI MX FO A R t k) ->
       forall (A R1 R2 : Type) (RR : R1 -> R2 -> Prop) (t1 : PTreeDefinition.ptree E MN R1)
         (t2 : PTreeDefinition.ptree E MN R2) (k1 : R1 -> PTreeDefinition.ptree E MN A)
         (k2 : R2 -> PTreeDefinition.ptree E MN A),
       @PEutt.peutt E MN MF FI FC MX FO R1 R2 RR t1 t2 ->
       (forall (r1 : R1) (r2 : R2),
        RR r1 r2 -> @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) (k1 r1) (k2 r2)) ->
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) (@PTreeDefinition.PTree.bind E MN R1 A t1 k1)
         (@PTreeDefinition.PTree.bind E MN R2 A t2 k2)

@ProbabilisticTrace.peutt_preserves_finite_interaction_sem
     : forall (E MN MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF)
         (FC : @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI),
       @TwoLevelMeasure.SemanticMeasureBindLaws MF FI ->
       @TwoLevelMeasure.SemanticMeasureCouplingAELaws MF FI ->
       forall (MX : TwoLevelMeasure.MixedMeasure MN MF) (FO : @TwoLevelMeasure.SemanticOmega MF FI),
       @TwoLevelMeasure.SemanticOmegaLaws MF FI FO ->
       @TwoLevelMeasure.SemanticMeasureOrderLaws MF FI FO ->
       forall (R1 R2 : Type) (RR : R1 -> R2 -> Prop)
         (tr : @ProbabilisticTrace.finite_interaction_pattern E)
         (t1 : PTreeDefinition.ptree E MN R1) (t2 : PTreeDefinition.ptree E MN R2),
       @PEutt.peutt E MN MF FI FC MX FO R1 R2 RR t1 t2 ->
       @TwoLevelMeasure.sem_lift MF FI bool bool (@eq bool)
         (@ProbabilisticTrace.finite_interaction_sem E MN MF FI MX FO R1 tr t1)
         (@ProbabilisticTrace.finite_interaction_sem E MN MF FI MX FO R2 tr t2)

@PEutt.peutt_prob
     : forall (E MN MF : Type -> Type) (NI : TwoLevelMeasure.SemanticMeasure MN)
         (FI : TwoLevelMeasure.SemanticMeasure MF),
       @TwoLevelMeasure.SemanticMeasureCoreLaws MN NI ->
       forall FC : @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI,
       @TwoLevelMeasure.SemanticMeasureBindLaws MF FI ->
       forall MX : TwoLevelMeasure.MixedMeasure MN MF,
       @TwoLevelMeasure.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @TwoLevelMeasure.SemanticOmega MF FI,
       @TwoLevelMeasure.SemanticMeasureOrderLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaCofinalityLaws MF FI FO ->
       @TwoLevelMeasure.MixedMeasureOmegaLaws MN MF NI FI MX FO ->
       forall (R1 R2 X1 X2 : Type) (RR : R1 -> R2 -> Prop) (XR : X1 -> X2 -> Prop)
         (mu1 : MN X1) (mu2 : MN X2) (k1 : X1 -> PTreeDefinition.ptree E MN R1)
         (k2 : X2 -> PTreeDefinition.ptree E MN R2),
       @TwoLevelMeasure.sem_lift MN NI X1 X2 XR mu1 mu2 ->
       (forall (x1 : X1) (x2 : X2),
        XR x1 x2 -> @PEutt.peutt E MN MF FI FC MX FO R1 R2 RR (k1 x1) (k2 x2)) ->
       @PEutt.peutt E MN MF FI FC MX FO R1 R2 RR
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN R1 (PTreeDefinition.ptree E MN R1) X1 mu1 k1
         |}
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN R2 (PTreeDefinition.ptree E MN R2) X2 mu2 k2
         |}

@PEutt.peutt_prob_rewrite
     : forall (E MN MF : Type -> Type) (NI : TwoLevelMeasure.SemanticMeasure MN)
         (FI : TwoLevelMeasure.SemanticMeasure MF),
       @TwoLevelMeasure.SemanticMeasureCoreLaws MN NI ->
       forall FC : @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI,
       @TwoLevelMeasure.SemanticMeasureBindLaws MF FI ->
       forall MX : TwoLevelMeasure.MixedMeasure MN MF,
       @TwoLevelMeasure.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @TwoLevelMeasure.SemanticOmega MF FI,
       @TwoLevelMeasure.SemanticMeasureOrderLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaCofinalityLaws MF FI FO ->
       @TwoLevelMeasure.MixedMeasureOmegaLaws MN MF NI FI MX FO ->
       forall (R X Y : Type) (S : Relation_Definitions.relation (PTreeDefinition.ptree E MN R)),
       @RelationClasses.subrelation (PTreeDefinition.ptree E MN R) S
         (@PEutt.peutt E MN MF FI FC MX FO R R (@eq R)) ->
       forall (XR : X -> Y -> Prop) (mu : MN X) (nu : MN Y)
         (k1 : X -> PTreeDefinition.ptree E MN R) (k2 : Y -> PTreeDefinition.ptree E MN R),
       @TwoLevelMeasure.sem_lift MN NI X Y XR mu nu ->
       (forall (x : X) (y : Y), XR x y -> S (k1 x) (k2 y)) ->
       @PEutt.peutt E MN MF FI FC MX FO R R (@eq R)
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN R (PTreeDefinition.ptree E MN R) X mu k1
         |}
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E MN R (PTreeDefinition.ptree E MN R) Y nu k2
         |}

@PEutt.peutt_ret
     : forall (E MN MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF)
         (FC : @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI),
       @TwoLevelMeasure.SemanticMeasureBindLaws MF FI ->
