       @TwoLevelMeasure.SemanticOmegaLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaCofinalityLaws MF FI FO ->
       forall (R1 R2 : Type) (RR : R1 -> R2 -> Prop) (r1 : R1) (r2 : R2),
       RR r1 r2 ->
       @PEutt.peutt E MN MF FI FC MX FO R1 R2 RR
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF E MN R1 (PTreeDefinition.ptree E MN R1) r1
         |}
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.RetF E MN R2 (PTreeDefinition.ptree E MN R2) r2
         |}

@PEutt.peutt_rewrite_l
     : forall (E MN MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF)
         (FC : @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI)
         (MX : TwoLevelMeasure.MixedMeasure MN MF) (FO : @TwoLevelMeasure.SemanticOmega MF FI)
         (A : Type) (R : Relation_Definitions.relation (PTreeDefinition.ptree E MN A)),
       @RelationClasses.subrelation (PTreeDefinition.ptree E MN A) R
         (@PEutt.peutt E MN MF FI FC MX FO A A (@eq A)) ->
       forall x x' y : PTreeDefinition.ptree E MN A,
       R x x' ->
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) x' y ->
       @PEutt.peutt E MN MF FI FC MX FO A A (@eq A) x y

@PEutt.peutt_rewrite_r
     : forall (E MN MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF)
         (FC : @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI)
         (MX : TwoLevelMeasure.MixedMeasure MN MF) (FO : @TwoLevelMeasure.SemanticOmega MF FI)
         (A : Type) (R : Relation_Definitions.relation (PTreeDefinition.ptree E MN A)),
