@WellFormedness.probabilistic_ptree
     : forall (E M : Type -> Type) (SI : TwoLevelMeasure.SemanticMeasure M),
       @TwoLevelMeasure.SemanticSubprobability M SI ->
       forall R : Type, PTreeDefinition.ptree E M R -> Prop

@WellFormedness.probabilistic_ptree_bind
     : forall (E M : Type -> Type) (SI : TwoLevelMeasure.SemanticMeasure M)
         (SP : @TwoLevelMeasure.SemanticSubprobability M SI) (T U : Type)
         (t : PTreeDefinition.ptree E M T) (k : T -> PTreeDefinition.ptree E M U),
       @WellFormedness.probabilistic_ptree E M SI SP T t ->
       (forall x : T, @WellFormedness.probabilistic_ptree E M SI SP U (k x)) ->
       @WellFormedness.probabilistic_ptree E M SI SP U (@PTreeDefinition.PTree.bind E M T U t k)

@WellFormedness.probabilistic_ptree_prob
     : forall (E M : Type -> Type) (SI : TwoLevelMeasure.SemanticMeasure M)
         (SP : @TwoLevelMeasure.SemanticSubprobability M SI) (R X : Type)
         (mu : M X) (k : X -> PTreeDefinition.ptree E M R),
       @TwoLevelMeasure.sem_subprob M SI SP X mu ->
       (forall x : X, @WellFormedness.probabilistic_ptree E M SI SP R (k x)) ->
       @WellFormedness.probabilistic_ptree E M SI SP R
         {|
           PTreeDefinition._observe :=
             @PTreeDefinition.ProbF E M R (PTreeDefinition.ptree E M R) X mu k
         |}

@WellFormedness.probabilistic_ptree_ret
