@PStrong.pstrong
     : forall (E M : Type -> Type) (MI : TwoLevelMeasure.SemanticMeasure M),
       @TwoLevelMeasure.SemanticMeasureCoreLaws M MI ->
       forall R1 R2 : Type,
       (R1 -> R2 -> Prop) -> PTreeDefinition.ptree E M R1 -> PTreeDefinition.ptree E M R2 -> Prop

@PStrong.pstrong_bind
     : forall (E M : Type -> Type) (MI : TwoLevelMeasure.SemanticMeasure M)
         (MC : @TwoLevelMeasure.SemanticMeasureCoreLaws M MI) (A1 A2 B1 B2 : Type)
         (RA : A1 -> A2 -> Prop) (RB : B1 -> B2 -> Prop) (k1 : A1 -> PTreeDefinition.ptree E M B1)
         (k2 : A2 -> PTreeDefinition.ptree E M B2),
       (forall (a1 : A1) (a2 : A2), RA a1 a2 -> @PStrong.pstrong E M MI MC B1 B2 RB (k1 a1) (k2 a2)) ->
       forall (t1 : PTreeDefinition.ptree E M A1) (t2 : PTreeDefinition.ptree E M A2),
       @PStrong.pstrong E M MI MC A1 A2 RA t1 t2 ->
       @PStrong.pstrong E M MI MC B1 B2 RB (@PTreeDefinition.PTree.bind E M A1 B1 t1 k1)
         (@PTreeDefinition.PTree.bind E M A2 B2 t2 k2)

@PStrong.pstrong_equivalence
     : forall (E M : Type -> Type) (MI : TwoLevelMeasure.SemanticMeasure M)
         (MC : @TwoLevelMeasure.SemanticMeasureCoreLaws M MI) (R : Type),
       @RelationClasses.Equivalence (PTreeDefinition.ptree E M R)
         (@PStrong.pstrong E M MI MC R R (@eq R))

@PStruct.pstruct
     : forall (E M : Type -> Type) (R1 R2 : Type),
