@PStruct.pstruct_equivalence
     : forall (E M : Type -> Type) (R : Type),
       @RelationClasses.Equivalence (PTreeDefinition.ptree E M R)
         (@PStruct.pstruct E M R R (@eq R))

@PStrong.pstruct_pstrong
     : forall (E M : Type -> Type) (MI : TwoLevelMeasure.SemanticMeasure M)
         (MC : @TwoLevelMeasure.SemanticMeasureCoreLaws M MI) (R1 R2 : Type)
         (RR : R1 -> R2 -> Prop) (t1 : PTreeDefinition.ptree E M R1)
         (t2 : PTreeDefinition.ptree E M R2),
       @PStruct.pstruct E M R1 R2 RR t1 t2 -> @PStrong.pstrong E M MI MC R1 R2 RR t1 t2

@PrimitiveStableHitting.stable_hitting
     : forall (MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF),
       @TwoLevelMeasure.SemanticOmega MF FI ->
       forall S A : Type, (S -> MF (PrimitiveStableHitting.stable_target S A)) -> S -> MF A -> Prop

@PrimitiveStableHitting.stable_hitting_exists
     : forall (MF : Type -> Type) (FI : TwoLevelMeasure.SemanticMeasure MF)
         (FO : @TwoLevelMeasure.SemanticOmega MF FI),
       @TwoLevelMeasure.SemanticMeasureOrderLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaLaws MF FI FO ->
       forall (S A : Type) (kernel : S -> MF (PrimitiveStableHitting.stable_target S A))
         (state : S),
       exists out : MF A, @PrimitiveStableHitting.stable_hitting MF FI FO S A kernel state out

@PEutt.stable_hitting_prob
     : forall (E MN MF : Type -> Type) (NI : TwoLevelMeasure.SemanticMeasure MN)
         (FI : TwoLevelMeasure.SemanticMeasure MF),
       @TwoLevelMeasure.SemanticMeasureCoreLaws MN NI ->
       @TwoLevelMeasure.SemanticMeasureCoreLaws MF FI ->
       @TwoLevelMeasure.SemanticMeasureBindLaws MF FI ->
       forall MX : TwoLevelMeasure.MixedMeasure MN MF,
       @TwoLevelMeasure.MixedMeasureLaws MN MF NI FI MX ->
       forall FO : @TwoLevelMeasure.SemanticOmega MF FI,
       @TwoLevelMeasure.SemanticMeasureOrderLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaLaws MF FI FO ->
       @TwoLevelMeasure.SemanticOmegaCofinalityLaws MF FI FO ->
       @TwoLevelMeasure.MixedMeasureOmegaLaws MN MF NI FI MX FO ->
       forall (R X : Type) (mu : MN X) (k : X -> PTreeDefinition.ptree E MN R)
         (front : X -> MF (UnifiedFrontier.stable_head E MN R)) (Good : X -> Prop),
       @TwoLevelMeasure.sem_ae MN NI X mu Good ->
       (forall x : X,
        Good x ->
        @PrimitiveStableHitting.stable_hitting MF FI FO
          (PTreeDefinition.ptreeF E MN R (PTreeDefinition.ptree E MN R))
