          (PTreeDefinition.ptreeF E MN A (PTreeDefinition.ptree E MN A))
          (PTreeDefinition.ptreeF E MN B (PTreeDefinition.ptree E MN B))
          (UnifiedFrontier.stable_head E MN A) (UnifiedFrontier.stable_head E MN B)
          (@PTreeKernel.ptree_primitive_kernel E MN MF FI MX A)
          (@PTreeKernel.ptree_primitive_kernel E MN MF FI MX B)
          (@PEutt.ptree_stable_head_rel E MN A B RR0)
          (@PEutt.bind_upto_closure E MN MF FI FC MX FO A B RR0 sim) s1 s2) ->
